const standingsList=standings;
function standingsCards(){let groups={};LEAGUE.standings.forEach(x=>(groups[x.division]??=[]).push(x));let title=name=>name.replace('American League ','').replace('National League ','').replace('East','東地区').replace('Central','中地区').replace('West','西地区'),league=name=>name.startsWith('American')?'AL':'NL';return `<div class="section-head standings-page-head"><div><span class="eyebrow">STANDINGS</span><h2>${LEAGUE.season} MLB順位表</h2></div><span class="note">球団をタップすると詳細を表示</span></div>${teamDirectory()}<div class="standings-card-grid">${Object.entries(groups).map(([name,rows])=>`<section class="standings-card panel"><header><span class="league-pill ${league(name).toLowerCase()}">${league(name)}</span><h3>${title(name)}</h3></header><div class="standings-columns"><span>#</span><span>チーム</span><span>勝敗</span><span>勝率</span><span>差</span><span>得失</span><span>連続</span></div><div class="standings-rows">${rows.sort((a,b)=>a.rank-b.rank).map(x=>`<div class="standings-row ${x.rank===1?'leader':''}"><span class="standing-rank">${x.rank}</span><button class="standing-team" data-open-team="${x.team_id}">${teamBadge(x.team_id,x.team,x.name)}<span><b>${x.team}</b><small>${x.name}</small></span></button><strong class="standing-record">${x.wins}-${x.losses}</strong><span>${statFmt(x.pct,3)}</span><span>${x.gb==='-'?'—':x.gb}</span><span class="run-diff ${x.run_diff>0?'positive':x.run_diff<0?'negative':''}">${x.run_diff>0?'+':''}${x.run_diff}</span><span class="streak ${String(x.streak).startsWith('W')?'win':String(x.streak).startsWith('L')?'loss':''}">${x.streak||'—'}</span></div>`).join('')}</div></section>`).join('')}</div>`}
function playoffRace(){let card=league=>`<div class="panel"><h3>${league==='AL'?'アメリカン・リーグ':'ナショナル・リーグ'}</h3><div class="playoff-list">${LEAGUE.standings.filter(x=>x.league===league).sort((a,b)=>(b.playoff_pct||0)-(a.playoff_pct||0)).map((x,i)=>`<button data-open-team="${x.team_id}"><span>${i+1}</span>${teamBadge(x.team_id,x.team,x.name)}<b>${x.team}</b><strong>${statFmt(x.playoff_pct,1)}%</strong><small>${statFmt(x.projected_wins,1)}勝予測</small></button>`).join('')}</div></div>`;return `<div class="section-head playoff-head"><div><span class="eyebrow">PLAYOFF RACE</span><h2>プレーオフ進出確率</h2></div><span class="note">独自5,000回シミュレーション</span></div><div class="grid2">${card('AL')}${card('NL')}</div><p class="note">現在の勝敗と得失点から推定。公式予測や賭けの助言ではありません。</p>`}
standings=function(){return state.teamId?teamDetail():standingsCards()+playoffRace()};
